contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address receiver, uint amount) public {
        // The contract `c` was deployed by this test contract, so msg.sender == owner
        // only exactly when `caller` equals address(this).  We cannot make c see a
        // different msg.sender than this contract, so we only exercise the owner path.
        bool isOwner = (caller == address(this));

        uint beforeC = address(c).balance;
        uint beforeR = receiver.balance;

        bool reverted;
        if (isOwner) {
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterR = receiver.balance;

        bool shouldSucceed = isOwner && receiver != address(0) && amount > 0 && beforeC >= amount;

        assert(
            (shouldSucceed && !reverted && afterC == beforeC - amount && afterR == beforeR + amount)
            || (!shouldSucceed && reverted && afterC == beforeC && afterR == beforeR)
        );
    }

    receive() external payable {}
}

